// Developer-only: snapshots are generated by the historical source, never user roots.
import { execFileSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, readdirSync, symlinkSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { DatabaseSync } from 'node:sqlite';
import sharp from 'sharp';
import { makeCli, credentialStore } from '../apps/desktop/tests/fixtures.mjs';
const revisions = { '0.7.2': '005015bce192ba6beffb3330fffc92fc58ed2177', '0.8.0': '3e4e4f3', '0.8.1': '1d17690c5bfe488e428f8069a8e05babcd667213' };
for (const [version, revision] of Object.entries(revisions)) {
  const sourceSha = execFileSync('git', ['rev-parse', revision], { encoding: 'utf8' }).trim();
  const temp = mkdtempSync(join(tmpdir(), 'shot-upgrade-generator-'));
  const source = join(temp, 'source'), root = join(temp, 'data'); mkdirSync(source); mkdirSync(root);
  try {
    const archive = join(temp, 'source.tar');
    execFileSync('git', ['archive', '--format=tar', `--output=${archive}`, sourceSha]);
    execFileSync('tar', ['-xf', archive, '-C', source]);
    symlinkSync(resolve('node_modules'), join(source, 'node_modules'), 'dir');
    const load = relative => import(pathToFileURL(join(source, relative)).href);
    const { LocalApp } = await load('packages/local/src/app.ts');
    const { FakeAgent, FAKE_PROFILE } = await load('packages/worker/src/fake.ts');
    const { DesktopController } = await load('packages/desktop/src/controller.ts');
    const { defaults, saveSettings } = await load('packages/desktop/src/settings.ts');
    const settings = defaults(); settings.delivery = { clipboard: 'manual' }; saveSettings(root, settings);
    const clipboard = { session: 'historical-synthetic', async sequence() { return '1'; }, async readImage() {}, async writeText() { return true; }, close() {} };
    const app = new LocalApp(root, new FakeAgent(), FAKE_PROFILE, { clipboard: 'manual', saveDirectory: join(root, 'exports') }, clipboard);
    const png = await sharp({ create: { width: 16, height: 16, channels: 3, background: 'purple' } }).png().toBuffer();
    const success = await app.submit(png, undefined, true); await app.work();
    const crashProfile = { ...FAKE_PROFILE, id: 'historical-crash' };
    app.setRegistry([{ adapter: new FakeAgent('crash'), profile: crashProfile }], crashProfile.id, crashProfile.version);
    await app.submit(png, undefined, true); await app.work();
    app.setRegistry([{ adapter: new FakeAgent(), profile: FAKE_PROFILE }], FAKE_PROFILE.id, FAKE_PROFILE.version);
    await app.submit(png, undefined, true);
    app.state.put(success, 'clipboard', { status: 'pending', attempts: 1 });
    const expected = app.list(); app.close();
    const workspace = join(root, 'workspace'); mkdirSync(workspace);
    const cli = makeCli(root, 'claude');
    const desktop = new DesktopController(root, clipboard, undefined, 'codex', async () => [], { credentials: credentialStore(), testGateway: async () => ({ status: 'synthetic_image_passed', requestsSent: 1, model: 'glm-5.3-flash' }) });
    const fields = { provider: 'claude-compatible-endpoint', id: 'historical-glm', path: cli, workspace, prompt: 'Synthetic upgrade fixture', endpoint: 'https://open.bigmodel.cn/api/anthropic', model: 'glm-5.3-flash' };
    await desktop.dispatch({ v: 1, command: 'create-profile', ...fields, token: 'synthetic-fixture-token', enableAfterTest: true });
    const selected = desktop.settings.agents.selected;
    await desktop.dispatch({ v: 1, command: 'create-profile', ...fields, editId: selected.id, editVersion: selected.version, reuseExisting: true, prompt: 'Synthetic edited prompt' });
    await desktop.close();
    const files = {}, databases = {};
    function walk(directory, prefix = '') {
      for (const e of readdirSync(directory, { withFileTypes: true })) {
        const relative = prefix + e.name, path = join(directory, e.name);
        if (e.isDirectory()) { walk(path, relative + '/'); continue; }
        if (relative.endsWith('.sqlite')) {
          const db = new DatabaseSync(path); const tables = db.prepare("SELECT name, sql FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'").all();
          databases[relative] = { userVersion: db.prepare('PRAGMA user_version').get().user_version, tables: tables.map(t => ({ ...t, rows: db.prepare(`SELECT * FROM "${t.name}"`).all() })), indexes: db.prepare("SELECT sql FROM sqlite_master WHERE type='index' AND sql IS NOT NULL").all().map(x => x.sql) }; db.close();
        } else if (!/\.sqlite-(wal|shm)$/.test(relative) && !relative.startsWith('npm/')) {
          const bytes = readFileSync(path);
          files[relative] = relative.endsWith('.json') ? { text: bytes.toString().split(root).join('@ROOT@') } : { base64: bytes.toString('base64') };
        }
      }
    }
    walk(root);
    writeFileSync(`scripts/fixtures/upgrades/${version}.json`, JSON.stringify({ version, sourceSha, expected, files, databases }, null, 2) + '\n');
    process.stdout.write(`PASS generated ${version} ${sourceSha} synthetic history, queue, unknown and shared credential references\n`);
  } finally { rmSync(temp, { recursive: true, force: true }); }
}
